1	import { db } from "../lib/db";
2	import { SANDBOX } from "../lib/sandbox";
3	import type { Job } from "@prisma/client";
4	
5	/**
6	 * SSL certificate issuance handler (SSL_ISSUE).
7	 *
8	 * `worker/index.ts` owns the job loop and the `handlers` map; wire this in there:
9	 *   SSL_ISSUE: sslIssue,
10	 *
11	 * Ownership + domain validation are enforced at enqueue time
12	 * (lib/actions-ssl.ts), so this handler trusts `payload.certId`.
13	 *
14	 * SAFETY: actually issuing a Let's Encrypt cert means SSHing to the customer's
15	 * VM and running certbot against a live, DNS-pointed domain. That is a real,
16	 * side-effecting operation, so it is DISABLED by default. Until the real path is
17	 * implemented and reviewed, this handler always takes the simulated-success
18	 * branch (which is also what SANDBOX/staging requires). No SSH is ever opened.
19	 */
20	
21	/** A Let's Encrypt certificate is valid for 90 days. */
22	const CERT_LIFETIME_MS = 90 * 86400_000;
23	
24	async function notify(userId: string, title: string, body?: string, href?: string) {
25	  try {
26	    await db.notification.create({ data: { userId, title, body, href } });
27	  } catch (e) {
28	    console.error("[ssl] notify failed", e);
29	  }
30	}
31	
32	export async function sslIssue(job: Job): Promise<void> {
33	  const payload = (job.payload ?? {}) as { certId?: string };
34	  if (!payload.certId) throw new Error("ssl job: missing certId");
35	
36	  const cert = await db.sslCertificate.findUnique({ where: { id: payload.certId } });
37	  if (!cert) throw new Error(`SslCertificate ${payload.certId} not found`);
38	
39	  // Mark in-flight so the UI shows "issuing" while we work.
40	  await db.sslCertificate.update({ where: { id: cert.id }, data: { status: "ISSUING" } });
41	
42	  try {
43	    // ---------------------------------------------------------------------
44	    // Real issuance path (SSH + certbot) — INTENTIONALLY NOT ENABLED.
45	    //
46	    // TODO(real-path): when we're ready to issue live certificates:
47	    //   1. Load the server (cert.serverId) and resolve its SSH endpoint
48	    //      (dedicated IP:22, or the platform public IP + forwarded ssh port).
49	    //   2. Pre-flight: confirm `cert.domain` resolves to that server's public
50	    //      IP (dig/getaddrinfo) so the ACME HTTP-01 challenge can succeed.
51	    //   3. SSH in and run certbot, e.g.:
52	    //        certbot certonly --non-interactive --agree-tos \
53	    //          -m <account-email> --webroot -w /var/www/html -d <domain>
54	    //      (or --standalone / an nginx plugin depending on the stack).
55	    //   4. Parse certbot output / read /etc/letsencrypt/live/<domain>/cert.pem
56	    //      for the real notAfter, and set issuedAt/expiresAt from it.
57	    //   5. Reload the customer's web server so the new cert is served.
58	    //
59	    // Guarded so the branch can never run accidentally: real issuance only
60	    // happens once ENABLE_REAL_SSL is explicitly set AND we're not in SANDBOX.
61	    // Until then we always fall through to the simulated success below.
62	    // ---------------------------------------------------------------------
63	    const realIssuanceEnabled = !SANDBOX && process.env.ENABLE_REAL_SSL === "1";
64	    if (realIssuanceEnabled) {
65	      // Not implemented yet — refuse rather than silently pretend.
66	      throw new Error("Real Let's Encrypt issuance is not implemented yet.");
67	    }
68	
69	    // Default: simulated success (SANDBOX-safe, no SSH, no certbot).
70	    const now = new Date();
71	    await db.sslCertificate.update({
72	      where: { id: cert.id },
73	      data: {
74	        status: "ACTIVE",
75	        issuedAt: now,
76	        expiresAt: new Date(now.getTime() + CERT_LIFETIME_MS),
77	        lastError: null,
78	      },
79	    });
80	    await notify(
81	      cert.userId,
82	      `SSL certificate issued for ${cert.domain}`,
83	      "Your Let's Encrypt certificate is active and valid for 90 days (sandbox).",
84	      "/dashboard/ssl"
85	    );
86	  } catch (e: any) {
87	    const reason = String(e?.message ?? e).slice(0, 500);
88	    await db.sslCertificate.update({
89	      where: { id: cert.id },
90	      data: { status: "FAILED", lastError: reason },
91	    });
92	    await notify(
93	      cert.userId,
94	      `SSL certificate failed for ${cert.domain}`,
95	      reason.slice(0, 200),
96	      "/dashboard/ssl"
97	    );
98	  }
99	}
