1	/**
2	 * Server-side SFTP proxy for the in-portal file manager.
3	 *
4	 * This is a plain (non-"use server") module so it can be imported by both the
5	 * server actions (lib/actions-files.ts) and the upload/download route handler.
6	 * It never runs in the browser — the customer's root credentials stay on the
7	 * server; the browser only ever talks to our own actions/route.
8	 *
9	 * Connection target is derived EXACTLY like the server detail page:
10	 *   - dedicated-IP servers connect to their own IP on port 22
11	 *   - NAT servers use PUBLIC_IP + the forwarded SSH port
12	 * Username is always "root"; password is `server.rootPassword`.
13	 *
14	 * SANDBOX: on staging (NXEON_SANDBOX=1) no real SSH connection is ever opened —
15	 * every op is backed by a small in-memory simulated filesystem so the whole
16	 * file-manager UX works end to end without a live VM.
17	 */
18	import SftpClient from "ssh2-sftp-client";
19	import { SANDBOX } from "./sandbox";
20	
21	/** The minimal shape of a Server we need to open a connection. */
22	export type SftpServer = {
23	  id: string;
24	  rootPassword: string | null;
25	  sshPort: number | null;
26	  dedicatedIp?: { address: string } | null;
27	};
28	
29	export type SftpEntry = {
30	  name: string;
31	  /** "d" directory, "-" file, "l" symlink, etc. (ssh2-sftp-client `type`). */
32	  type: string;
33	  isDirectory: boolean;
34	  size: number;
35	  /** Unix mtime in ms. */
36	  modifiedMs: number;
37	  /** Numeric permission bits (e.g. 0o644), or null if unknown. */
38	  mode: number | null;
39	};
40	
41	export type SftpStat = {
42	  isDirectory: boolean;
43	  size: number;
44	  modifiedMs: number;
45	  mode: number | null;
46	};
47	
48	const CONNECT_TIMEOUT_MS = 10_000;
49	
50	/** Max length for any absolute path we accept from the client. */
51	export const MAX_PATH_LEN = 4096;
52	/** Max length for a single path segment (file/folder name). */
53	export const MAX_NAME_LEN = 255;
54	
55	/**
56	 * Normalize + validate an absolute POSIX path coming from the browser. Rejects
57	 * relative paths, `..` traversal, NUL bytes, and over-long paths. Returns a
58	 * cleaned absolute path (collapsed slashes, resolved `.`), always starting with
59	 * "/". Throws on anything suspicious — callers surface the message.
60	 */
61	export function normalizePath(input: string): string {
62	  if (typeof input !== "string") throw new Error("Invalid path.");
63	  if (input.length > MAX_PATH_LEN) throw new Error("Path is too long.");
64	  if (input.includes("\0")) throw new Error("Invalid path.");
65	  if (!input.startsWith("/")) throw new Error("Path must be absolute.");
66	
67	  const out: string[] = [];
68	  for (const part of input.split("/")) {
69	    if (part === "" || part === ".") continue;
70	    if (part === "..") throw new Error("Path traversal is not allowed.");
71	    if (part.length > MAX_NAME_LEN) throw new Error("A path segment is too long.");
72	    out.push(part);
73	  }
74	  return "/" + out.join("/");
75	}
76	
77	/**
78	 * Validate a single new file/folder name — no slashes, no traversal, no NUL,
79	 * not "." or "..". Returns the name unchanged if valid.
80	 */
81	export function validateName(name: string): string {
82	  if (typeof name !== "string" || name.length === 0) throw new Error("A name is required.");
83	  if (name.length > MAX_NAME_LEN) throw new Error("Name is too long.");
84	  if (name.includes("/") || name.includes("\0")) throw new Error("Name contains invalid characters.");
85	  if (name === "." || name === "..") throw new Error("That name is not allowed.");
86	  return name;
87	}
88	
89	/** Join a validated absolute dir with a validated name, re-normalizing. */
90	export function joinPath(dir: string, name: string): string {
91	  return normalizePath(`${dir}/${name}`);
92	}
93	
94	/**
95	 * Resolve the {host, port} for a server, mirroring the server detail page:
96	 * dedicated IP -> :22, otherwise PUBLIC_IP:sshPort.
97	 */
98	export function connectionTarget(server: SftpServer): { host: string; port: number } | null {
99	  const dedicated = !!server.dedicatedIp;
100	  const host = dedicated ? server.dedicatedIp!.address : process.env.PUBLIC_IP || "";
101	  const port = dedicated ? 22 : server.sshPort;
102	  if (!host || !port) return null;
103	  return { host, port };
104	}
105	
106	/**
107	 * Open an SFTP connection, run `fn(client)`, and ALWAYS close it (finally).
108	 * In SANDBOX mode this is bypassed entirely — callers below short-circuit to
109	 * the in-memory filesystem before ever reaching here.
110	 */
111	export async function withSftp<T>(
112	  server: SftpServer,
113	  fn: (client: SftpClient) => Promise<T>
114	): Promise<T> {
115	  if (SANDBOX) {
116	    throw new Error("withSftp must not be called in sandbox mode");
117	  }
118	  const target = connectionTarget(server);
119	  if (!target) throw new Error("Server is not reachable yet — connection details are pending.");
120	  if (!server.rootPassword) throw new Error("Server has no root password set.");
121	
122	  const client = new SftpClient();
123	  try {
124	    await client.connect({
125	      host: target.host,
126	      port: target.port,
127	      username: "root",
128	      password: server.rootPassword,
129	      readyTimeout: CONNECT_TIMEOUT_MS,
130	    });
131	    return await fn(client);
132	  } finally {
133	    try {
134	      await client.end();
135	    } catch {
136	      /* best-effort close */
137	    }
138	  }
139	}
