141	// ----------------------------------------------------------------------------
142	// Sandbox in-memory filesystem
143	// ----------------------------------------------------------------------------
144	
145	type SimNode =
146	  | { type: "dir"; mtime: number; mode: number; children: Record<string, SimNode> }
147	  | { type: "file"; mtime: number; mode: number; content: string };
148	type SimDir = Extract<SimNode, { type: "dir" }>;
149	
150	/** One simulated filesystem per server id, lazily seeded. */
151	const globalForSim = globalThis as unknown as { __nxeonSftpSim?: Map<string, SimNode> };
152	const simStore: Map<string, SimNode> = globalForSim.__nxeonSftpSim ?? new Map();
153	globalForSim.__nxeonSftpSim = simStore;
154	
155	function seedSim(): SimNode {
156	  const now = Date.now();
157	  const file = (content: string, mode = 0o644): SimNode => ({
158	    type: "file",
159	    mtime: now,
160	    mode,
161	    content,
162	  });
163	  const dir = (children: Record<string, SimNode>, mode = 0o755): SimNode => ({
164	    type: "dir",
165	    mtime: now,
166	    mode,
167	    children,
168	  });
169	  return dir({
170	    root: dir({
171	      "readme.txt": file(
172	        "Welcome to your VPS (sandbox).\n\nThis is a simulated filesystem shown on the staging\nenvironment — no real SSH connection is made.\n"
173	      ),
174	      ".bashrc": file("# ~/.bashrc\nexport PATH=$PATH:/usr/local/bin\n"),
175	      projects: dir({
176	        "app.js": file("console.log('hello from your server');\n"),
177	        "notes.md": file("# Notes\n\n- Edit me from the file manager.\n"),
178	      }),
179	    }),
180	    etc: dir({
181	      "hostname": file("nxeon-vps\n"),
182	      "os-release": file('PRETTY_NAME="Ubuntu 24.04 LTS"\n', 0o644),
183	    }),
184	    var: dir({
185	      log: dir({
186	        "syslog": file("Jan  1 00:00:00 nxeon-vps systemd[1]: Started sandbox.\n"),
187	      }),
188	      www: dir({
189	        html: dir({
190	          "index.html": file("<!doctype html><h1>It works</h1>\n"),
191	        }),
192	      }),
193	    }),
194	    tmp: dir({}),
195	  });
196	}
197	
198	function simRoot(serverId: string): SimNode {
199	  let node = simStore.get(serverId);
200	  if (!node) {
201	    node = seedSim();
202	    simStore.set(serverId, node);
203	  }
204	  return node;
205	}
206	
207	/** Convert an rwx rights triad ("rwx","r-x","r--") into an octal mode integer. */
208	function rightsToMode(rights: { user: string; group: string; other: string }): number | null {
209	  if (!rights) return null;
210	  const bits = (s: string): number =>
211	    (s.includes("r") ? 4 : 0) + (s.includes("w") ? 2 : 0) + (s.includes("x") ? 1 : 0);
212	  return (bits(rights.user) << 6) | (bits(rights.group) << 3) | bits(rights.other);
213	}
214	
215	function splitPath(p: string): string[] {
216	  return p.split("/").filter((s) => s.length > 0);
217	}
218	
219	function simResolve(serverId: string, p: string): SimNode | null {
220	  let node = simRoot(serverId);
221	  for (const part of splitPath(p)) {
222	    if (node.type !== "dir") return null;
223	    const next = node.children[part];
224	    if (!next) return null;
225	    node = next;
226	  }
227	  return node;
228	}
229	
230	function simParent(serverId: string, p: string): { parent: SimDir; name: string } | null {
231	  const parts = splitPath(p);
232	  if (parts.length === 0) return null;
233	  const name = parts[parts.length - 1];
234	  const parentPath = "/" + parts.slice(0, -1).join("/");
235	  const parent = simResolve(serverId, parentPath);
236	  if (!parent || parent.type !== "dir") return null;
237	  return { parent, name };
238	}
239	
240	// ----------------------------------------------------------------------------
241	// Typed operations (sandbox-aware)
242	// ----------------------------------------------------------------------------
243	
244	export async function listDir(server: SftpServer, path: string): Promise<SftpEntry[]> {
245	  if (SANDBOX) {
246	    const node = simResolve(server.id, path);
247	    if (!node) throw new Error("No such directory.");
248	    if (node.type !== "dir") throw new Error("Not a directory.");
249	    return Object.entries(node.children)
250	      .map(([name, child]) => ({
251	        name,
252	        type: child.type === "dir" ? "d" : "-",
253	        isDirectory: child.type === "dir",
254	        size: child.type === "file" ? Buffer.byteLength(child.content) : 0,
255	        modifiedMs: child.mtime,
256	        mode: child.mode,
257	      }))
258	      .sort((a, b) =>
259	        a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1
260	      );
261	  }
262	
263	  return withSftp(server, async (client) => {
264	    const list = await client.list(path);
265	    return list
266	      .map((e) => ({
267	        name: e.name,
268	        type: e.type,
269	        isDirectory: e.type === "d",
270	        size: e.size,
271	        modifiedMs: e.modifyTime,
272	        // ssh2-sftp-client's list() returns rwx `rights` strings, not a numeric
273	        // mode — derive the octal permission bits from them.
274	        mode: rightsToMode(e.rights),
275	      }))
276	      .sort((a, b) =>
277	        a.isDirectory === b.isDirectory ? a.name.localeCompare(b.name) : a.isDirectory ? -1 : 1
278	      );
279	  });
280	}
281	
282	export async function statPath(server: SftpServer, path: string): Promise<SftpStat> {
283	  if (SANDBOX) {
284	    const node = simResolve(server.id, path);
285	    if (!node) throw new Error("No such file or directory.");
286	    return {
287	      isDirectory: node.type === "dir",
288	      size: node.type === "file" ? Buffer.byteLength(node.content) : 0,
289	      modifiedMs: node.mtime,
290	      mode: node.mode,
291	    };
292	  }
293	
294	  return withSftp(server, async (client) => {
295	    const s = await client.stat(path);
296	    return {
297	      isDirectory: s.isDirectory,
298	      size: s.size,
299	      modifiedMs: s.modifyTime,
300	      mode: typeof s.mode === "number" ? s.mode & 0o777 : null,
301	    };
302	  });
303	}
304	
305	/**
306	 * Read a text file, capped at `maxBytes`. Throws if the target is larger than
307	 * the cap so we never buffer an unbounded file into memory / the editor.
308	 */
309	export async function readFileText(
310	  server: SftpServer,
311	  path: string,
312	  maxBytes: number
313	): Promise<string> {
314	  if (SANDBOX) {
315	    const node = simResolve(server.id, path);
316	    if (!node) throw new Error("No such file.");
317	    if (node.type !== "file") throw new Error("Not a file.");
318	    if (Buffer.byteLength(node.content) > maxBytes) {
319	      throw new Error("File is too large to edit in the browser.");
320	    }
321	    return node.content;
322	  }
323	
324	  return withSftp(server, async (client) => {
325	    const s = await client.stat(path);
326	    if (s.isDirectory) throw new Error("Not a file.");
327	    if (s.size > maxBytes) throw new Error("File is too large to edit in the browser.");
328	    const buf = (await client.get(path)) as Buffer;
329	    return buf.toString("utf8");
330	  });
331	}
332	
333	export async function writeFileText(
334	  server: SftpServer,
335	  path: string,
336	  content: string
337	): Promise<void> {
338	  if (SANDBOX) {
339	    const loc = simParent(server.id, path);
340	    if (!loc) throw new Error("Invalid path.");
341	    const existing = loc.parent.children[loc.name];
342	    if (existing && existing.type === "dir") throw new Error("Path is a directory.");
343	    loc.parent.children[loc.name] = {
344	      type: "file",
345	      mtime: Date.now(),
346	      mode: existing?.type === "file" ? existing.mode : 0o644,
347	      content,
348	    };
349	    return;
350	  }
351	
352	  await withSftp(server, async (client) => {
353	    await client.put(Buffer.from(content, "utf8"), path);
354	  });
355	}
356	
357	export async function mkdirPath(server: SftpServer, path: string): Promise<void> {
358	  if (SANDBOX) {
359	    const loc = simParent(server.id, path);
360	    if (!loc) throw new Error("Invalid path.");
361	    if (loc.parent.children[loc.name]) throw new Error("A file or folder with that name already exists.");
362	    loc.parent.children[loc.name] = { type: "dir", mtime: Date.now(), mode: 0o755, children: {} };
363	    return;
364	  }
365	
366	  await withSftp(server, async (client) => {
367	    await client.mkdir(path, false);
368	  });
369	}
370	
371	export async function renamePath(
372	  server: SftpServer,
373	  from: string,
374	  to: string
375	): Promise<void> {
376	  if (SANDBOX) {
377	    const src = simResolve(server.id, from);
378	    if (!src) throw new Error("No such file or directory.");
379	    const dst = simParent(server.id, to);
380	    if (!dst) throw new Error("Invalid destination.");
381	    if (dst.parent.children[dst.name]) {
382	      throw new Error("A file or folder with that name already exists.");
383	    }
384	    const srcLoc = simParent(server.id, from);
385	    if (!srcLoc) throw new Error("Cannot rename the root.");
386	    delete srcLoc.parent.children[srcLoc.name];
387	    dst.parent.children[dst.name] = { ...src, mtime: Date.now() };
388	    return;
389	  }
390	
391	  await withSftp(server, async (client) => {
392	    await client.rename(from, to);
393	  });
394	}
395	
396	/** Remove a file, or recursively remove a directory. */
397	export async function removePath(server: SftpServer, path: string): Promise<void> {
398	  if (SANDBOX) {
399	    const loc = simParent(server.id, path);
400	    if (!loc) throw new Error("Cannot remove the root.");
401	    if (!loc.parent.children[loc.name]) throw new Error("No such file or directory.");
402	    delete loc.parent.children[loc.name];
403	    return;
404	  }
405	
406	  await withSftp(server, async (client) => {
407	    const s = await client.stat(path);
408	    if (s.isDirectory) {
409	      await client.rmdir(path, true); // recursive
410	    } else {
411	      await client.delete(path);
412	    }
413	  });
414	}
415	
416	export async function chmodPath(server: SftpServer, path: string, mode: number): Promise<void> {
417	  if (SANDBOX) {
418	    const node = simResolve(server.id, path);
419	    if (!node) throw new Error("No such file or directory.");
420	    node.mode = mode & 0o777;
421	    return;
422	  }
423	
424	  await withSftp(server, async (client) => {
425	    await client.chmod(path, mode & 0o777);
426	  });
427	}
428	
429	// ----------------------------------------------------------------------------
430	// Streaming helpers for the upload/download route
431	// ----------------------------------------------------------------------------
432	
433	/** Read an entire file into a Buffer (used by the download endpoint). */
434	export async function readFileBuffer(server: SftpServer, path: string): Promise<Buffer> {
435	  if (SANDBOX) {
436	    const node = simResolve(server.id, path);
437	    if (!node) throw new Error("No such file.");
438	    if (node.type !== "file") throw new Error("Not a file.");
439	    return Buffer.from(node.content, "utf8");
440	  }
441	
442	  return withSftp(server, async (client) => {
443	    const s = await client.stat(path);
444	    if (s.isDirectory) throw new Error("Not a file.");
445	    return (await client.get(path)) as Buffer;
446	  });
447	}
448	
449	/** Write a Buffer to a path (used by the upload endpoint). */
450	export async function writeFileBuffer(
451	  server: SftpServer,
452	  path: string,
453	  data: Buffer
454	): Promise<void> {
455	  if (SANDBOX) {
456	    const loc = simParent(server.id, path);
457	    if (!loc) throw new Error("Invalid path.");
458	    const existing = loc.parent.children[loc.name];
459	    if (existing && existing.type === "dir") throw new Error("Path is a directory.");
460	    loc.parent.children[loc.name] = {
461	      type: "file",
462	      mtime: Date.now(),
463	      mode: existing?.type === "file" ? existing.mode : 0o644,
464	      content: data.toString("utf8"),
465	    };
466	    return;
467	  }
468	
469	  await withSftp(server, async (client) => {
470	    await client.put(data, path);
471	  });
472	}
